use std :: collections :: HashMap ; use std :: fs ; use std :: process :: Command ; use std :: path :: Path ; fn test_file_io_operations () -> Result < () , String > { let test_content = "Test content for file I/O test" ; let test_path = "./test_io.txt" ; fs :: write (test_path , test_content) . map_err (| e | format ! ("Failed to write test file: {}" , e)) ? ; let read_content = fs :: read_to_string (test_path) . map_err (| e | format ! ("Failed to read test file: {}" , e)) ? ; assert_eq ! (read_content , test_content) ; fs :: remove_file (test_path) . map_err (| e | format ! ("Failed to clean up test file: {}" , e)) ? ; println ! ("    ✓ File I/O operations test passed") ; Ok (()) }